#!/usr/bin/env node
/**
 * Emits {namespace}.generated.ts next to each YAML (with .json fallback when YAML is empty)
 * for central locales under packages/i18n, and for each app under packages/app-store
 * (apps ... / translations / {locale}).
 *
 * Regional / partial locales deep-merge their parent chain into the generated file
 * so runtime loaders always see a complete message tree.
 */
import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";
import { parse as parseYaml } from "yaml";
import {
  deepMergeMessages,
  fallbackLanguage,
  getLocaleChain,
  localeParents,
} from "../src/locale-catalog.ts";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const LOCALES_DIR = path.join(__dirname, "../src/locales");
const APPS_DIR = path.join(__dirname, "../../app-store/src/apps");

function isEmptyObject(obj) {
  return (
    obj == null ||
    (typeof obj === "object" &&
      !Array.isArray(obj) &&
      Object.keys(obj).length === 0)
  );
}

/**
 * @param {string} localeDir - directory that contains e.g. admin.yaml / admin.json
 * @param {string} stem - namespace (admin, public, …)
 */
function loadSourceObject(localeDir, stem) {
  const yamlPath = path.join(localeDir, `${stem}.yaml`);
  if (fs.existsSync(yamlPath)) {
    const raw = fs.readFileSync(yamlPath, "utf8");
    let doc;
    if (raw.trim()) {
      try {
        doc = parseYaml(raw);
      } catch (e) {
        throw new Error(`Invalid YAML: ${yamlPath}: ${e.message}`);
      }
    } else {
      doc = null;
    }
    if (
      doc != null &&
      typeof doc === "object" &&
      !Array.isArray(doc) &&
      !isEmptyObject(doc)
    ) {
      return doc;
    }
  }
  const jsonPath = path.join(localeDir, `${stem}.json`);
  if (fs.existsSync(jsonPath)) {
    return JSON.parse(fs.readFileSync(jsonPath, "utf8"));
  }
  return {};
}

/**
 * Deep-merge parent chain (root -> leaf) for one namespace.
 * @param {string} baseRoot
 * @param {string} locale
 * @param {string} stem
 */
function loadMergedSourceObject(baseRoot, locale, stem) {
  const chain = getLocaleChain(locale);
  let result = {};
  for (const loc of [...chain].reverse()) {
    const data = loadSourceObject(path.join(baseRoot, loc), stem);
    result = deepMergeMessages(result, data);
  }
  return result;
}

function getStemsInLocaleDir(localeDir) {
  if (!fs.existsSync(localeDir)) return [];
  const stems = new Set();
  for (const f of fs.readdirSync(localeDir)) {
    if (f.endsWith(".generated.ts") || f.startsWith(".")) continue;
    // Skip draft/helper fragments (e.g. `_pageTemplates.fragment.yaml`) -
    // dots in the stem break namespace-loaders object keys.
    if (f.startsWith("_")) continue;
    const m = f.match(/^([a-zA-Z][a-zA-Z0-9_-]*)\.(json|yaml|yml)$/);
    if (!m) continue;
    stems.add(m[1]);
  }
  return [...stems].sort();
}

function getStemsForLocaleBase(baseLocalesRoot, baseLocale) {
  return getStemsInLocaleDir(path.join(baseLocalesRoot, baseLocale));
}

function getSubdirs(root) {
  if (!fs.existsSync(root)) return [];
  return fs
    .readdirSync(root, { withFileTypes: true })
    .filter((d) => d.isDirectory())
    .map((d) => d.name);
}

function getAppNames() {
  return getSubdirs(APPS_DIR).sort();
}

function isPlainObject(value) {
  return value != null && typeof value === "object" && !Array.isArray(value);
}

/**
 * Leaf paths, matching the old `Leaves` type: empty objects are leaves,
 * nested objects are walked, everything else is a leaf.
 * @param {unknown} value
 * @param {string} prefix
 * @param {string[]} out
 */
function collectLeafKeys(value, prefix, out) {
  if (!isPlainObject(value)) {
    if (prefix) out.push(prefix);
    return;
  }

  const keys = Object.keys(value);
  if (keys.length === 0) {
    if (prefix) out.push(prefix);
    return;
  }

  for (const key of keys) {
    const next = prefix ? `${prefix}.${key}` : key;
    if (isPlainObject(value[key])) {
      collectLeafKeys(value[key], next, out);
    } else {
      out.push(next);
    }
  }
}

function objectToTypeScriptValue(value, indent) {
  const pad = " ".repeat(indent);
  if (value === null) return "null";
  if (typeof value === "string") {
    return JSON.stringify(value);
  }
  if (typeof value === "number" || typeof value === "boolean") {
    return String(value);
  }
  if (Array.isArray(value)) {
    if (value.length === 0) return "[]";
    const lines = value.map(
      (v) => `${pad}  ${objectToTypeScriptValue(v, indent + 2)}`,
    );
    return `[\n${lines.join(",\n")}\n${pad}]`;
  }
  if (typeof value === "object") {
    const keys = Object.keys(value);
    if (keys.length === 0) return "{}";
    const lines = keys.map(
      (k) =>
        `${pad}  ${JSON.stringify(k)}: ${objectToTypeScriptValue(value[k], indent + 2)}`,
    );
    return `{\n${lines.join(",\n")}\n${pad}}`;
  }
  return "undefined";
}

const header = `// Generated by packages/i18n/scripts/generate-locales-from-yaml.mjs - do not edit.
// Source: .yaml (with .json fallback while migrating). Re-run: yarn generate-locales
`;

const messagesType = `type TranslationMessage =
  | string
  | number
  | boolean
  | null
  | TranslationMessage[]
  | { [key: string]: TranslationMessage };
`;

const keysHeader = `// Generated by packages/i18n/scripts/generate-locales-from-yaml.mjs - do not edit.
// Flat key map for the language server. Re-run: yarn generate-locales
`;

function writeGeneratedFile(outPath, data) {
  const body = `${header}${messagesType}
const messages: { [key: string]: TranslationMessage } = ${objectToTypeScriptValue(data, 0)};
export default messages;
`;
  fs.writeFileSync(outPath, body, "utf8");
}

/**
 * @param {string} interfaceName
 * @param {string} typeName
 * @param {string[]} keys
 */
function renderKeyMap(interfaceName, typeName, keys) {
  if (keys.length === 0) {
    return `export type ${typeName} = never;\n`;
  }
  return `export interface ${interfaceName} {
${keys.map((key) => `  ${JSON.stringify(key)}: string;`).join("\n")}
}
export type ${typeName} = keyof ${interfaceName};
`;
}

/**
 * @param {string} outPath
 * @param {{ interfaceName: string, typeName: string, keys: string[] }[]} maps
 */
function writeKeyMapFile(outPath, maps) {
  fs.writeFileSync(
    outPath,
    `${keysHeader}${maps
      .map((map) => renderKeyMap(map.interfaceName, map.typeName, map.keys))
      .join("\n")}`,
    "utf8",
  );
}

const loaderHeader = `// Generated by packages/i18n/scripts/generate-locales-from-yaml.mjs - do not edit.
// Static import paths (no interpolated locale) so bundlers can include message chunks. Re-run: yarn generate-locales
`;

/**
 * @param {string} localeDir
 * @param {string[]} stems
 */
function writeNamespaceLoadersFile(localeDir, stems) {
  if (!fs.existsSync(localeDir)) {
    fs.mkdirSync(localeDir, { recursive: true });
  }
  const entries = stems
    .map((stem) => `  ${stem}: () => import("./${stem}.generated")`)
    .join(",\n");
  const body = `${loaderHeader}export const namespaceLoaders = {
${entries},
} as const;
`;
  fs.writeFileSync(
    path.join(localeDir, "namespace-loaders.generated.ts"),
    body,
    "utf8",
  );
}

/**
 * @param {string} transRoot - parent of en/, uk/, …
 * @param {string[]} localeCodes
 */
function writeLocaleNamespaceLoadersRegistry(transRoot, localeCodes) {
  const sorted = [...localeCodes].sort();
  const isSafeIdent = (s) => /^[a-zA-Z_$][\w$]*$/.test(s);
  const loaderEntries = sorted
    .map((loc) => {
      const key = isSafeIdent(loc) ? loc : JSON.stringify(loc);
      return `  ${key}: () => import("./${loc}/namespace-loaders.generated")`;
    })
    .join(",\n");
  const parentEntries = Object.entries(localeParents)
    .map(([child, parent]) => {
      const childKey = isSafeIdent(child) ? child : JSON.stringify(child);
      return `  ${childKey}: ${JSON.stringify(parent)}`;
    })
    .join(",\n");
  const body = `${loaderHeader}export type MessageLocale = keyof typeof localeNamespaceLoaders;

export const localeNamespaceLoaders = {
${loaderEntries},
} as const;

const localeParents: Record<string, string> = {
${parentEntries},
};

export function resolveMessageLocale(locale: string): MessageLocale {
  const seen = new Set<string>();
  let current: string | undefined = locale;
  while (current && !seen.has(current)) {
    seen.add(current);
    if (current in localeNamespaceLoaders) {
      return current as MessageLocale;
    }
    current = localeParents[current];
  }
  if (${JSON.stringify(fallbackLanguage)} in localeNamespaceLoaders) {
    return ${JSON.stringify(fallbackLanguage)} as MessageLocale;
  }
  return Object.keys(localeNamespaceLoaders)[0] as MessageLocale;
}
`;
  fs.writeFileSync(
    path.join(transRoot, "locale-namespace-loaders.generated.ts"),
    body,
    "utf8",
  );
}

/**
 * @param {string} baseRoot
 * @param {string[]} stems
 * @param {string[]} localeCodes
 */
function emitLoaderModules(baseRoot, stems, localeCodes) {
  if (stems.length === 0 || localeCodes.length === 0) {
    return;
  }
  for (const loc of localeCodes) {
    writeNamespaceLoadersFile(path.join(baseRoot, loc), stems);
  }
  writeLocaleNamespaceLoadersRegistry(baseRoot, localeCodes);
}

function generateForTranslationTree(options) {
  const { baseRoot, baseLocale, logLabel, emitBaseAllKeys, keyPrefix } =
    options;
  const stems = getStemsForLocaleBase(baseRoot, baseLocale);
  if (stems.length === 0) {
    return { generated: 0, keys: 0 };
  }

  const locales = getSubdirs(baseRoot);
  const baseAllKeys = [];
  let count = 0;
  let keyFileCount = 0;
  for (const locale of locales) {
    const localeDir = path.join(baseRoot, locale);
    for (const stem of stems) {
      const data = loadMergedSourceObject(baseRoot, locale, stem);
      const outPath = path.join(localeDir, `${stem}.generated.ts`);
      writeGeneratedFile(outPath, data);
      count++;
      if (locale !== baseLocale) continue;

      const leaves = [];
      collectLeafKeys(data, "", leaves);
      leaves.sort();
      const maps = [
        { interfaceName: "KeyMap", typeName: "Keys", keys: leaves },
      ];
      if (keyPrefix) {
        const prefix = keyPrefix(stem);
        maps.push({
          interfaceName: "PrefixedKeyMap",
          typeName: "PrefixedKeys",
          keys: leaves.map((leaf) => `${prefix}.${leaf}`),
        });
      }

      writeKeyMapFile(path.join(localeDir, `${stem}.keys.d.ts`), maps);
      keyFileCount++;
      if (!emitBaseAllKeys) continue;

      for (const leaf of leaves) {
        baseAllKeys.push(`${stem}.${leaf}`);
      }
    }
  }

  if (emitBaseAllKeys) {
    baseAllKeys.sort();
    writeKeyMapFile(path.join(baseRoot, baseLocale, "base-all.keys.d.ts"), [
      {
        interfaceName: "BaseAllKeyMap",
        typeName: "BaseAllKeys",
        keys: baseAllKeys,
      },
    ]);
    keyFileCount++;
  }

  emitLoaderModules(baseRoot, stems, locales);
  if (count > 0 && logLabel) {
    console.log(
      `${logLabel}: ${count} file(s) (${stems.length} namespace(s) × ${locales.length} locale(s)), ${keyFileCount} key declaration(s).`,
    );
  }
  return { generated: count, keys: keyFileCount };
}

function main() {
  const core = generateForTranslationTree({
    baseRoot: LOCALES_DIR,
    baseLocale: "en",
    logLabel: "generate-locales (packages/i18n central)",
    emitBaseAllKeys: true,
  });

  let appTotal = 0;
  let appKeys = 0;
  for (const appName of getAppNames()) {
    const transRoot = path.join(APPS_DIR, appName, "translations");
    if (!fs.existsSync(transRoot)) continue;
    const enDir = path.join(transRoot, "en");
    if (!fs.existsSync(enDir)) continue;
    const n = generateForTranslationTree({
      baseRoot: transRoot,
      baseLocale: "en",
      logLabel: null,
      keyPrefix: (stem) => `app_${appName}_${stem}`,
    });
    appTotal += n.generated;
    appKeys += n.keys;
  }
  if (appTotal > 0) {
    console.log(
      `generate-locales (app-store, all apps): ${appTotal} file(s), ${appKeys} key declaration(s) under packages/app-store/src/apps/**/translations/.`,
    );
  }

  const total = core.generated + appTotal;
  if (total === 0) {
    console.warn("generate-locales-from-yaml: no translation stems found.");
  } else {
    console.log(
      `generate-locales-from-yaml: total ${total} .generated.ts file(s) (central: ${core.generated}, apps: ${appTotal}), ${core.keys + appKeys} .keys.d.ts file(s).`,
    );
  }
}

main();
